"""Frozen approval content, sender expiry, event integration, occasions and quiet-hour delivery."""
from support import Client,sql
import pathlib,json,uuid,datetime,time
results=[]
def check(name,ok,data=None):
 results.append({'test':name,'passed':bool(ok)});pathlib.Path('test-results/phase5-extended.json').write_text(json.dumps(results,indent=2));print(('PASS ' if ok else 'FAIL ')+name,flush=True);assert ok,(name,data)
def good(c,p,m='GET',d=None,status=200):
 code,b=c.req('/communications'+p,m,d);assert code==status,(p,code,b);return b
def until(fn,timeout=25):
 end=time.monotonic()+timeout
 while time.monotonic()<end:
  value=fn()
  if value:return value
  time.sleep(.2)
 raise AssertionError('Timed out waiting for worker')
def login(email,role,org=None):
 c=Client();assert c.login(email)[0]==200;w=next(w for w in c.req('/workspaces')[1] if w['role']==role and (org is None or w['orgId']==org));c.activate(w);return c,w
club=sql("SELECT \"Id\" FROM \"Orgs\" WHERE \"Code\"='GC-006'");district=sql("SELECT \"Id\" FROM \"Orgs\" WHERE \"Code\"='GC-004'");tag=uuid.uuid4().hex[:8]
admin,root=login('admin@example.test','Association Super Admin');root=next(w for w in admin.req('/workspaces')[1] if w['role']=='Association Super Admin' and w['association'].startswith('Global'));admin.activate(root)
review,_=login('secretary@example.test','Association Super Admin',root['orgId']);member,_=login('member@example.test','Club Member',club);manager,_=login('manager@example.test','Club Manager',club)
uid=lambda e:sql(f"SELECT \"Id\" FROM \"Users\" WHERE \"Email\"='{e}'")
mid=uid('member@example.test');managerid=uid('manager@example.test');pid=sql(f"SELECT \"Id\" FROM \"Persons\" WHERE \"UserId\"='{mid}'")
def approve_request(id):
 r=admin.req('/governance/requests/'+id)[1]['request'];code,b=review.req('/governance/requests/'+id+'/decisions','POST',{'decision':'Approve','comment':'Independent extended fixture review','version':r['version']});assert code==200,b

def create(**kw):return good(admin,'/campaigns','POST',{'orgId':club,'title':'Extended campaign '+tag,'body':'Hello {{member_name}}, an official update.','channel':'InApp','purpose':'Transactional','rules':json.dumps({'orgId':club}),**kw})
def submit(b):return good(admin,'/campaigns/'+b['id']+'/status','POST',{'action':'Submit','version':b['version']})
def approve(b):
 b=submit(b);approve_request(b['approvalRequestId']);return good(admin,'/campaigns/'+b['id'])['broadcast']
def schedule(b):return good(admin,'/campaigns/'+b['id']+'/status','POST',{'action':'Schedule','version':b['version']})
b=submit(create());proposal=admin.req('/governance/requests/'+b['approvalRequestId'])[1]['communication'];check('reviewers receive actual frozen body and audience count',proposal['body']==b['body'] and proposal['recipients']>0);check('approval recipient preview keeps contact details private',all('email' not in p and 'phone' not in p for p in proposal['sample']))
r=admin.req('/governance/requests/'+b['approvalRequestId'])[1]['request'];code,data=review.req('/governance/requests/'+r['id']+'/decisions','POST',{'decision':'Reject','comment':'Reject fixture notice','version':r['version']});check('shared rejection marks campaign rejected',code==200 and good(admin,'/campaigns/'+b['id'])['broadcast']['status']=='Rejected')
# Communication-only district role cannot read unrelated shared governance proposals.
role=str(uuid.uuid4());assignment=str(uuid.uuid4());sql(f"""INSERT INTO "Roles"("Id","TenantId","Name") VALUES('{role}','{root['tenantId']}','Communication-only district {tag}');INSERT INTO "RolePermissions"("Id","RoleId","PermissionId") SELECT gen_random_uuid(),'{role}',"Id" FROM "Permissions" WHERE "Id" IN('communications.view','communications.manage','communications.reports');INSERT INTO "Assignments"("Id","UserId","TenantId","RoleId","OrgId") VALUES('{assignment}','{managerid}','{root['tenantId']}','{role}','{district}');""")
manager.activate(next(w for w in manager.req('/workspaces')[1] if w['id']==assignment))
code,resolution=admin.req('/governance/resolutions','POST',{'orgId':district,'number':'PRIVATE-'+tag,'title':'Private governance '+tag,'subject':'Governance only','text':'Confidential fixture proposal','date':datetime.datetime.now(datetime.timezone.utc).isoformat(),'effectiveAt':datetime.datetime.now(datetime.timezone.utc).isoformat()});assert code==200,resolution
requestid=resolution.get('requestId') or resolution.get('approvalRequestId') or resolution['request']['id'];check('communication-only role cannot access unrelated governance proposal',manager.req('/governance/requests/'+requestid)[0]==404)
feed=manager.req('/governance/requests')[1];rows=feed.get('items',feed if isinstance(feed,list) else []);check('communication-only governance feed contains only communication requests',all(x.get('kind','').startswith('Communication') for x in rows))
expiring_user=str(uuid.uuid4());expiring_email='comm-expiry-'+tag+'@example.test';sql(f"""INSERT INTO "Users" SELECT(jsonb_populate_record(NULL::"Users",to_jsonb(u)||jsonb_build_object('Id','{expiring_user}','Email','{expiring_email}','PlatformAdmin',false))).* FROM "Users" u WHERE u."Id"='{managerid}';INSERT INTO "UserProfiles" SELECT(jsonb_populate_record(NULL::"UserProfiles",to_jsonb(u)||jsonb_build_object('Id','{expiring_user}','Name','Fictional expiring sender'))).* FROM "UserProfiles" u WHERE u."Id"='{managerid}';INSERT INTO "Assignments"("Id","UserId","TenantId","RoleId","OrgId") VALUES(gen_random_uuid(),'{expiring_user}','{root['tenantId']}','{role}','{district}');""");expiring,_=login(expiring_email,'Communication-only district '+tag,district)
scheduled=good(expiring,'/campaigns','POST',{'orgId':district,'title':'Expired sender '+tag,'body':'Scoped district update','channel':'InApp','purpose':'Transactional','rules':json.dumps({'orgId':club})});scheduled=good(expiring,'/campaigns/'+scheduled['id']+'/status','POST',{'action':'Submit','version':scheduled['version']});approve_request(scheduled['approvalRequestId']);scheduled=good(expiring,'/campaigns/'+scheduled['id'])['broadcast'];sql(f"DELETE FROM \"RolePermissions\" WHERE \"RoleId\"='{role}' AND \"PermissionId\"='communications.manage'");sql(f"UPDATE \"CommunicationBroadcasts\" SET \"Status\"='Scheduled' WHERE \"Id\"='{scheduled['id']}'");until(lambda:good(admin,'/campaigns/'+scheduled['id'])['broadcast']['status']=='Failed');check('worker rechecks sender authority before fan-out',sql(f"SELECT count(*) FROM \"CommunicationMessages\" WHERE \"BroadcastId\"='{scheduled['id']}'")=='0')
# Quiet hours defer delivery rather than silently reporting delivered.
now=datetime.datetime.now(datetime.timezone.utc);hour=now.hour;sql(f"UPDATE \"UserProfiles\" SET \"TimeZone\"='UTC' WHERE \"Id\"='{mid}'")
good(member,'/preferences','PUT',{'channel':'InApp','transactional':True,'promotional':True,'quietEnabled':True,'quietStart':hour,'quietEnd':(hour+1)%24});quiet=schedule(approve(create(title='Quiet-hour fixture '+tag)));mail=lambda:sql(f"SELECT m.\"Id\" FROM \"Mails\" m JOIN \"CommunicationMessages\" x ON x.\"Id\"=m.\"CommunicationId\" WHERE x.\"BroadcastId\"='{quiet['id']}' AND m.\"UserId\"='{mid}' AND m.\"SentAt\" IS NULL AND m.\"NextAttemptAt\">now()+interval '1 minute'")
qid=until(mail);check('recipient quiet hours persist a deferred delivery time',bool(qid));good(member,'/preferences','PUT',{'channel':'InApp','transactional':True,'promotional':True,'birthday':True});sql(f"UPDATE \"Mails\" SET \"NextAttemptAt\"=now() WHERE \"Id\"='{qid}'");until(lambda:sql(f"SELECT \"DeliveryStatus\" FROM \"Mails\" WHERE \"Id\"='{qid}'")=='Delivered');check('deferred in-app delivery resumes from durable outbox',True)
# Real event registration writes provenance into the shared outbox; event-trigger automation resolves its variables.
t=good(admin,'/templates','POST',{'orgId':club,'name':'Event-context follow-up '+tag,'body':'Hello {{member_name}}, thank you for registering for {{event_name}} at {{event_location}}.','channel':'InApp'});rule=good(admin,'/automations','POST',{'orgId':club,'name':'Event registration follow-up '+tag,'trigger':'event.registration','templateId':t['id']});rule=good(admin,'/automations/'+rule['id']+'/submit','POST',{});approve_request(rule['approvalRequestId'])
at=lambda h:(datetime.datetime.now(datetime.timezone.utc)+datetime.timedelta(hours=h)).isoformat();etype=admin.req('/event-types')[1][0]['id'];code,event=admin.req('/events','POST',{'orgId':club,'typeId':etype,'title':'Actual registration signal '+tag,'startsAt':at(2),'endsAt':at(4),'registrationStartsAt':at(-1),'registrationEndsAt':at(3),'venue':'A real fictional event venue','capacity':10});assert code==200,event;eid=event['id'];sql(f"UPDATE \"Events\" SET \"Approval\"='Approved',\"Publication\"='Published' WHERE \"Id\"='{eid}'");code,reg=member.req('/events/'+eid+'/registrations','POST',{});assert code==200,reg
source=until(lambda:sql(f"SELECT \"Id\" FROM \"Mails\" WHERE \"EventId\"='{eid}' AND \"Kind\"='event.update' AND \"UserId\"='{mid}' AND \"Body\" LIKE '%Registration confirmed%' LIMIT 1"));check('event registration uses shared notification outbox with event provenance',bool(source));execution=until(lambda:sql(f"SELECT \"MailId\" FROM \"CommunicationExecutions\" WHERE \"AutomationId\"='{rule['id']}' AND \"SourceKey\"='{source}'"));body=sql(f"SELECT \"Body\" FROM \"Mails\" WHERE \"Id\"='{execution}'");check('event automation resolves actual event variables',event['title'] in body and event['venue'] in body and '{{' not in body)
# Campaign event details are frozen at submission, so a later event update cannot silently alter approved communication.
frozen=approve(create(title='Frozen event communication '+tag,eventId=eid,body='You are invited to {{event_name}} at {{event_location}}.'));sql(f"UPDATE \"Events\" SET \"Venue\"='Changed after campaign approval' WHERE \"Id\"='{eid}'");schedule(frozen);until(lambda:good(admin,'/campaigns/'+frozen['id'])['broadcast']['status'] in ['Completed','Partially Completed']);check('approved campaign keeps reviewed event personalization snapshot',sql(f"SELECT count(*) FROM \"CommunicationMessages\" WHERE \"BroadcastId\"='{frozen['id']}' AND \"Body\" LIKE '%Changed after%' ")=='0')
# Updating a template leaves an approved automation inactive for the changed version.
ruledata=next(r for r in good(admin,'/automations') if r['id']==rule['id']);t=good(admin,'/templates/'+t['id'],'PUT',{'orgId':club,'name':t['name'],'body':'A changed follow-up {{member_name}}','channel':'InApp','version':t['version']});changed=good(admin,'/automations/'+rule['id'],'PUT',{'orgId':club,'name':ruledata['name'],'trigger':ruledata['trigger'],'templateId':t['id'],'version':ruledata['version']});check('editing an automation invalidates its prior approval',changed['status']=='Draft' and not changed['active'])
# Birthday privacy has two gates; restore the private date and policy after fixture assertions.
old_date=sql(f"SELECT COALESCE(\"BirthDate\"::text,'') FROM \"Persons\" WHERE \"Id\"='{pid}'");old_birthday=sql(f"SELECT \"BirthdayAnnouncements\" FROM \"PersonPrivacy\" WHERE \"PersonId\"='{pid}'")
try:
 birthday=good(admin,'/templates','POST',{'orgId':club,'name':'Occasion greeting '+tag,'body':'Hello {{member_name}}, wishing you a wonderful day.','channel':'InApp'});br=good(admin,'/automations','POST',{'orgId':club,'name':'Occasion consent '+tag,'trigger':'Birthday','templateId':birthday['id'],'dailyLimit':1});br=good(admin,'/automations/'+br['id']+'/submit','POST',{});approve_request(br['approvalRequestId']);sql(f"UPDATE \"Persons\" SET \"BirthDate\"='1990-{now.month:02}-{now.day:02}' WHERE \"Id\"='{pid}';UPDATE \"PersonPrivacy\" SET \"BirthdayAnnouncements\"=true WHERE \"PersonId\"='{pid}'");good(member,'/preferences','PUT',{'channel':'InApp','transactional':True,'promotional':True,'birthday':False});time.sleep(2);check('birthday automation honors occasion preference',sql(f"SELECT count(*) FROM \"CommunicationExecutions\" WHERE \"AutomationId\"='{br['id']}'")=='0');good(member,'/preferences','PUT',{'channel':'InApp','transactional':True,'promotional':True,'birthday':True});until(lambda:sql(f"SELECT count(*) FROM \"CommunicationExecutions\" WHERE \"AutomationId\"='{br['id']}'")=='1');time.sleep(2);check('birthday automation runs at most once per day and recipient',sql(f"SELECT count(*) FROM \"CommunicationExecutions\" WHERE \"AutomationId\"='{br['id']}'")=='1')
finally:
 sql(f"UPDATE \"Persons\" SET \"BirthDate\"="+("'"+old_date+"'" if old_date else 'NULL')+f" WHERE \"Id\"='{pid}';UPDATE \"PersonPrivacy\" SET \"BirthdayAnnouncements\"={'true' if old_birthday=='t' else 'false'} WHERE \"PersonId\"='{pid}';UPDATE \"CommunicationAutomations\" SET \"Active\"=false WHERE \"Id\"='{br['id']}'")
print(len(results),'extended communication checks passed',flush=True)
